UPDATE campus_ingest_task
source_id = #{sourceId}, task_name = #{taskName}, target_type = #{targetType}, adapter_type = #{adapterType}, schedule_cron = #{scheduleCron}, schedule_enabled = #{scheduleEnabled}, fetch_config = #{fetchConfig}, task_status = #{taskStatus}, last_run_time = #{lastRunTime}, next_run_time = #{nextRunTime}, schedule_lock_until = #{scheduleLockUntil}, max_retry_count = #{maxRetryCount}, retry_interval_minutes = #{retryIntervalMinutes}, consecutive_fail_count = #{consecutiveFailCount}, current_retry_count = #{currentRetryCount}, last_error_type = #{lastErrorType}, auto_detect_enabled = #{autoDetectEnabled}, detection_task_ids = #{detectionTaskIds}, daily_quota_limit = #{dailyQuotaLimit}, daily_quota_used = #{dailyQuotaUsed}, quota_stat_date = #{quotaStatDate}, auto_pause_after_fail_count = #{autoPauseAfterFailCount}, governance_remark = #{governanceRemark}, authorization_scope = #{authorizationScope}, retention_days = #{retentionDays}, update_user_id = #{updateUserId}
WHERE task_id = #{taskId} AND deleted = 0

UPDATE campus_ingest_task
SET task_status = #{taskStatus},
    update_user_id = #{updateUserId}
WHERE task_id = #{taskId}
  AND deleted = 0

UPDATE campus_ingest_task
SET last_run_time = NOW(),
    update_user_id = #{updateUserId}
WHERE task_id = #{taskId}
  AND deleted = 0

UPDATE campus_ingest_task
SET next_run_time = #{nextRunTime},
    update_user_id = #{updateUserId}
WHERE task_id = #{taskId}
  AND deleted = 0

UPDATE campus_ingest_task
SET daily_quota_used = 0,
    quota_stat_date = #{quotaStatDate},
    update_user_id = #{updateUserId}
WHERE task_id = #{taskId}
  AND deleted = 0

UPDATE campus_ingest_task
SET daily_quota_used = IFNULL(daily_quota_used, 0) + #{costUnits},
    quota_stat_date = #{quotaStatDate},
    update_user_id = #{updateUserId}
WHERE task_id = #{taskId}
  AND deleted = 0

UPDATE campus_ingest_task
SET deleted = 1,
    update_user_id = #{updateUserId}
WHERE task_id = #{taskId}
  AND deleted = 0

