SELECT 
FROM campus_ingest_task
WHERE deleted = 0

    AND (task_name LIKE CONCAT('%', #{keyword}, '%') OR authorization_scope LIKE CONCAT('%', #{keyword}, '%'))


    AND source_id = #{sourceId}


    AND target_type = #{targetType}


    AND task_status = #{taskStatus}

ORDER BY id DESC
